    // species 8: C2
    species[8] = +2.252892330000000e+00 + 1.231903070000000e-03 * T -
                 4.503541560000000e-07 * T2 + 7.493566559999999e-11 * T3 -
                 4.579250770000000e-15 * T4;
    // species 9: C2H
    species[9] = +2.662702480000000e+00 + 3.824922520000000e-03 * T -
                 1.366325000000000e-06 * T2 + 2.134550400000000e-10 * T3 -
                 1.232168480000000e-14 * T4;
    // species 10: C2H2
    species[10] = +3.658784890000000e+00 + 4.883966670000000e-03 * T -
                  1.608288880000000e-06 * T2 + 2.469745440000000e-10 * T3 -
                  1.386059590000000e-14 * T4;
    // species 11: C2H3
    species[11] = +3.150267630000000e+00 + 7.540213410000000e-03 * T -
                  2.629978470000000e-06 * T2 + 4.159740480000000e-10 * T3 -
                  2.454075090000000e-14 * T4;
    // species 12: C2H4
    species[12] = +2.991827240000000e+00 + 1.048339080000000e-02 * T -
                  3.717213420000000e-06 * T2 + 5.946283660000000e-10 * T3 -
                  3.536303860000000e-14 * T4;
