  // reaction 6:  C2H + CH4 <=> C2H2 + CH3
  k_f = 1806640;
  qf[18] *= k_f;
  qr[18] *= k_f * exp(-(-g_RT[6] + g_RT[7] + g_RT[9] - g_RT[10]));
  // reaction 7:  2 C2H2 <=> H + H2CCCCH
  k_f = 1933.11 * exp(-(29106.051950145) * invT);
  qf[19] *= k_f;
