  // reaction 8:  C2H + H2 <=> C2H2 + H
  k_f = 10779600 * exp(-(1089.46408146722) * invT);
  qf[20] *= k_f;
  qr[20] *= k_f * exp(-(g_RT[0] - g_RT[1] + g_RT[9] - g_RT[10]));
