  qf[28] *= k_f;
  qr[28] *= k_f * exp(-(-g_RT[1] + g_RT[3] + g_RT[4] - g_RT[10]));
  // reaction 20:  CH + CH3 <=> C2H3 + H
  k_f = 29990300;
  qf[29] *= k_f;
  qr[29] *= k_f * exp(-(-g_RT[1] + g_RT[3] + g_RT[6] - g_RT[11]));
  // reaction 21:  C2H3 + CH <=> C2H2 + CH2
  k_f = 49983800;
  qf[30] *= k_f;
  qr[30] *= k_f * exp(-(g_RT[3] - g_RT[4] - g_RT[10] + g_RT[11]));
  // reaction 22:  2 CH2 <=> C2H2 + H2
  k_f = 12044300 * exp(-(400.560465980557) * invT);
  qf[31] *= k_f;
  qr[31] *= k_f * exp(-(-g_RT[0] + 2.000000 * g_RT[4] - g_RT[10]));
  // reaction 23:  2 CH2 <=> C2H2 + 2 H
  k_f = 107796000 * exp(-(400.560465980557) * invT);
  qf[32] *= k_f;
  qr[32] *= k_f * exp(-(-2.000000 * g_RT[1] + 2.000000 * g_RT[4] - g_RT[10])) *
            (refCinv);
  // reaction 24:  CH2 + CH3 <=> C2H4 + H
  k_f = 42155000;
  qf[33] *= k_f;
  qr[33] *= k_f * exp(-(-g_RT[1] + g_RT[4] + g_RT[6] - g_RT[12]));
  // reaction 25:  C2H3 + CH2 <=> C2H2 + CH3
  k_f = 18066400;
  qf[34] *= k_f;
  qr[34] *= k_f * exp(-(g_RT[4] - g_RT[6] - g_RT[10] + g_RT[11]));
  // reaction 26:  CH2(S) + M <=> CH2 + M
  k_f = 15055400;
  Corr = mixture;
  qf[3] *= Corr * k_f;
  qr[3] *= Corr * k_f * exp(-(-g_RT[4] + g_RT[5]));
  // reaction 27:  2 CH3 + M <=> C2H6 + M
  k_f = 3.62662e+29 * exp((-7) * logT - (1390.38764761844) * invT);
  Corr = mixture;
  qf[4] *= Corr * k_f;
  qr[4] *= Corr * k_f * exp(-(2.000000 * g_RT[6] - g_RT[14])) * (refC);
  // reaction 28:  CH3 + M <=> CH2 + H + M
  k_f = 29086900000 * exp(-(45596.4620885656) * invT);
  Corr = mixture;
  qf[5] *= Corr * k_f;
  qr[5] *= Corr * k_f * exp(-(-g_RT[1] - g_RT[4] + g_RT[6])) * (refCinv);
  // reaction 29:  C2H + C2H3 <=> 2 C2H2
  k_f = 18969700;
  qf[35] *= k_f;
  qr[35] *= k_f * exp(-(g_RT[9] - 2.000000 * g_RT[10] + g_RT[11]));
  // reaction 30:  H2CCCCH + M <=> C4H2 + H + M
  k_f = 11201200000 * exp(-(23404.6071265775) * invT);
  Corr = mixture;
  qf[6] *= Corr * k_f;
  qr[6] *= Corr * k_f * exp(-(-g_RT[1] - g_RT[18] + g_RT[19])) * (refCinv);
  // reaction 31:  C2H2 + H + M <=> C2H3 + M
  k_f = 3427150 * exp(-(739.728498732938) * invT);
  Corr = mixture;
  qf[7] *= Corr * k_f;
  qr[7] *= Corr * k_f * exp(-(g_RT[1] + g_RT[10] - g_RT[11])) * (refC);
  // reaction 32:  C2H2 + CH <=> C2H + CH2
  k_f = 210775000 * exp(-(-86.5532665184118) * invT);
  qf[36] *= k_f;
  qr[36] *= k_f * exp(-(g_RT[3] - g_RT[4] - g_RT[9] + g_RT[10]));
  // reaction 33:  C2H2 + CH2 <=> C3H4
  k_f = 12044300 * exp(-(3331.29432762724) * invT);
  qf[37] *= k_f;
  qr[37] *= k_f * exp(-(g_RT[4] + g_RT[10] - g_RT[16])) * (refC);
  // reaction 34:  C2H2 + CH2(S) <=> C3H3 + H
  k_f = 174642000;
  qf[38] *= k_f;
  qr[38] *= k_f * exp(-(-g_RT[1] + g_RT[5] + g_RT[10] - g_RT[15]));
  // reaction 35:  C2H + C2H2 <=> C4H2 + H
  k_f = 89729900;
  qf[39] *= k_f;
  qr[39] *= k_f * exp(-(-g_RT[1] + g_RT[9] + g_RT[10] - g_RT[18]));
  // reaction 36:  C2H2 + M <=> C2H + H + M
  k_f = 113818000000 * exp(-(53758.6364079182) * invT);
  Corr = mixture;
  qf[8] *= Corr * k_f;
  qr[8] *= Corr * k_f * exp(-(-g_RT[1] - g_RT[9] + g_RT[10])) * (refCinv);
  // reaction 37:  C2H4 + H <=> C2H3 + H2
  k_f = 541993000 * exp(-(7497.92832049032) * invT);
  qf[40] *= k_f;
  qr[40] *= k_f * exp(-(-g_RT[0] + g_RT[1] - g_RT[11] + g_RT[12]));
  // reaction 38:  C2H4 + H + M <=> C2H5 + M
  k_f = 13418500 * exp(-(379.928582682563) * invT);
  Corr = mixture;
  qf[9] *= Corr * k_f;
  qr[9] *= Corr * k_f * exp(-(g_RT[1] + g_RT[12] - g_RT[13])) * (refC);
  // reaction 39:  C2H4 + CH <=> C3H4 + H
  k_f = 131885000 * exp(-(-173.106533036824) * invT);
  qf[41] *= k_f;
  qr[41] *= k_f * exp(-(-g_RT[1] + g_RT[3] + g_RT[12] - g_RT[16]));
  // reaction 40:  C2H4 + CH2(S) <=> C3H6
  k_f = 96400000;
  qf[42] *= k_f;
  qr[42] *= k_f * exp(-(g_RT[5] + g_RT[12] - g_RT[17])) * (refC);
  // reaction 41:  C2H4 + CH3 <=> C2H3 + CH4
  k_f = 4161300 * exp(-(5599.79505707492) * invT);
  qf[43] *= k_f;
  qr[43] *= k_f * exp(-(g_RT[6] - g_RT[7] - g_RT[11] + g_RT[12]));
  // reaction 42:  C2H4 + M <=> C2H2 + H2 + M
  k_f = 99365300000 * exp(-(36000.1202716696) * invT);
  Corr = mixture;
  qf[10] *= Corr * k_f;
  qr[10] *= Corr * k_f * exp(-(-g_RT[0] - g_RT[10] + g_RT[12])) * (refCinv);
  // reaction 43:  C2H4 + M <=> C2H3 + H + M
  k_f = 758790000000 * exp(-(48600.6655834198) * invT);
  Corr = mixture;
  qf[11] *= Corr * k_f;
  qr[11] *= Corr * k_f * exp(-(-g_RT[1] - g_RT[11] + g_RT[12])) * (refCinv);
  // reaction 44:  C2H6 + H <=> C2H5 + H2
  k_f = 1451.34 * exp(-(3729.33871027878) * invT);
  qf[44] *= k_f;
  qr[44] *= k_f * exp(-(-g_RT[0] + g_RT[1] - g_RT[13] + g_RT[14]));
  // reaction 45:  C2H6 + CH <=> C2H4 + CH3
  k_f = 107796000 * exp(-(-132.345983106641) * invT);
  qf[45] *= k_f;
  qr[45] *= k_f * exp(-(g_RT[3] - g_RT[6] - g_RT[12] + g_RT[14]));
  // reaction 46:  C2H6 + CH2(S) <=> C2H5 + CH3
  k_f = 239681000;
  qf[46] *= k_f;
  qr[46] *= k_f * exp(-(g_RT[5] - g_RT[6] - g_RT[13] + g_RT[14]));
  // reaction 47:  C2H6 + CH3 <=> C2H5 + CH4
  k_f = 1.51156e-13 * exp((6) * logT - (3042.44796145534) * invT);
  qf[47] *= k_f;
  qr[47] *= k_f * exp(-(g_RT[6] - g_RT[7] - g_RT[13] + g_RT[14]));
